async #loadView(id) {
  this.#hideViews();

  let view = this.#modal.querySelector(id);
  if (view) {
    view.hidden = false;
    this.#currentView = view;
    await view.ready;
    return;
  }
  view = document.createElement(id);
  this.#modal.appendChild(view);
  this.#currentView = view;
  await view.ready;
}
